func TestRewindFixturePinsRejectChangeMissingAndUnknown(t *testing.T) {
	source := "../../../contracts/examples/v0.2"
	dir := t.TempDir()
	entries, err := os.ReadDir(source)
	if err != nil {
		t.Fatal(err)
	}
	for _, entry := range entries {
		raw, e := os.ReadFile(filepath.Join(source, entry.Name()))
		if e != nil {
			t.Fatal(e)
		}
		if e = os.WriteFile(filepath.Join(dir, entry.Name()), raw, 0600); e != nil {
			t.Fatal(e)
		}
	}
	check := func() error { _, e := verifyContractFixtureCorpus(dir, "../../../contracts/v0.2"); return e }
	if e := check(); e != nil {
		t.Fatal("nominal corpus", e)
	}
	path := filepath.Join(dir, "rewind_guest_reset.valid.json")
	raw, e := os.ReadFile(path)
	if e != nil {
		t.Fatal(e)
	}
	if e = os.WriteFile(path, append(append([]byte(nil), raw...), ' '), 0600); e != nil {
		t.Fatal(e)
	}
	if check() == nil {
		t.Fatal("changed new fixture accepted")
	}
	if e = os.Remove(path); e != nil {
		t.Fatal(e)
	}
	if check() == nil {
		t.Fatal("missing new fixture accepted")
	}
	if e = os.WriteFile(path, raw, 0600); e != nil {
		t.Fatal(e)
	}
	if e = os.WriteFile(filepath.Join(dir, "rewind_unknown.valid.json"), []byte(`{}`), 0600); e != nil {
		t.Fatal(e)
	}
	if check() == nil {
		t.Fatal("unrecorded new fixture accepted")
	}
}
